let total = java.getElements('class.anthology-list-play size');
let n=total.length
java.log(JSON.stringify(n))

//路线名称获取
let r=src.match(/<\/i>&nbsp;.*?<span class=\"badge\">/g)
//java.log(JSON.stringify(r))
//路线提取文本
let tt=[];

for(let i=0;i<n;i++){
	let m = java.getElements(`class.anthology-list-play size.${i}@li@a`);

	tt.push({
		name:r[`${i}`].replace(/<\/i>&nbsp;/,"").replace(/<span class\=\"badge\">/,""),
		link:"",
		volume:true
		})

		Array.from(m).forEach(x=>{
	tt.push({
		name:x.text(),
		link:x.attr("href")
		})
		})
		java.log(JSON.stringify(tt))
		tt
}

